\centering
\small
\begin{tabular}{lcccccccc}
\toprule
Method & Budget & Gen\,0 PPL & Gen\,7 PPL & $\Delta$\% & Sel.\ Ratio & Rare n-gram & RankMe & $n$ \\
\midrule
